import sec1 from '../img/sec/01.jpg';
import sec2 from '../img/sec/02.jpg';
import sec3 from '../img/sec/03.jpg';
import sec4 from '../img/sec/04.jpg';
import { Swiper, SwiperSlide } from 'swiper/react';
import 'swiper/css';
import 'swiper/css/navigation';
import 'swiper/css/pagination';
import 'swiper/css/scrollbar';
import { Navigation, Pagination, Scrollbar, A11y } from 'swiper';

export default function Slider() {
return (
 

<Swiper
      // install Swiper modules
      modules={[Navigation, Pagination, Scrollbar, A11y]}
      spaceBetween={50}
      slidesPerView={3}
      navigation
      pagination={{ clickable: true }}
      scrollbar={{ draggable: true }}
      onSwiper={(swiper) => console.log(swiper)}
      onSlideChange={() => console.log('slide change')}
    >
      <SwiperSlide><img src={sec1} alt="" /></SwiperSlide>
      <SwiperSlide><img src={sec2} alt="" /></SwiperSlide>
      <SwiperSlide><img src={sec3} alt="" /></SwiperSlide>
      <SwiperSlide><img src={sec4} alt="" /></SwiperSlide>
      ...
    </Swiper>







);
}
